def keep_one_available_officer_per_department(apps, schema_editor):
    OfficerProfile = apps.get_model("accounts", "OfficerProfile")
    BusinessApplication = apps.get_model("applications", "BusinessApplication")
    database = schema_editor.connection.alias
    active_statuses = [
        "SUBMITTED", "UNDER_REVIEW", "DOCUMENT_VERIFICATION",
        "CLARIFICATION_REQUIRED", "CLARIFICATION_REQUESTED", "FIELD_VERIFICATION",
    ]

    department_ids = OfficerProfile.objects.using(database).filter(available=True).values_list("department_id", flat=True).distinct()
